const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '语义清图 · 非原像素修复' },
      { kind: 'text', payload: '选择题　第1题' },
      { kind: 'text', payload: '选择题　第2题' },
      { kind: 'text', payload: '填空题　第3题' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var mx = W * 0.07;
    var my = H * 0.06;
    var left = mx + W * 0.07;
    var right = W - mx - W * 0.07;
    var top = my + H * 0.13;
    var blockH = (H - my - H * 0.16 - top) / 3;
    var paths = [];
    var nodes = [];

    paths.push({ id: 'page', commands: [['M', mx, my], ['L', W - mx, my], ['L', W - mx, H - my], ['L', mx, H - my], ['Z']] });
    nodes.push({ type: 'path', pathId: 'page', fill: '#FFFFFF', stroke: { width: 2 } });

    for (var i = 0; i < 3; i++) {
      var y = top + i * blockH;
      paths.push({ id: 'rule' + i, commands: [['M', left, y + 4], ['L', right, y + 4]] });
      nodes.push({ type: 'path', pathId: 'rule' + i, fill: '#9AA3B2', stroke: { width: 1 } });
      paths.push({ id: 'bar' + i, commands: [['M', left - 10, y - 22], ['L', left - 10, y + 4]] });
      nodes.push({ type: 'path', pathId: 'bar' + i, fill: '#2C3E5A', stroke: { width: 2 } });
      nodes.push({ type: 'label', contentId: metrics[i + 1].contentId, anchor: { x: left, y: y - 6 }, hAlign: 'left', vAlign: 'bottom', color: '#1F2430' });
    }

    nodes.push({ type: 'label', contentId: metrics[0].contentId, anchor: { x: (left + right) / 2, y: H - my - 8 }, hAlign: 'center', vAlign: 'bottom', color: '#6B7280' });

    return { schemaVersion: 1, sceneId: 'clean-page', revision: input.revision, viewBox: { x: 0, y: 0, width: W, height: H }, paths: paths, root: { type: 'group', children: nodes } };
  }
};
